// LexicalAnalysis.cpp : 此文件包含 "main" 函数。程序执行将在此处开始并结束。
//
#include <iostream>
#include <cstring>
#include <fstream>
#include <sstream>
#include <vector>
#include <algorithm>
#include <ctype.h>
#include <set>
#include <iomanip>
#include <map>
using namespace std;

namespace {
const int kIllegalTokenType = 18;
string g_source_file_name;

bool readAllText(const string& fileName, string& text) {
	ifstream in(fileName.c_str(), ios::in | ios::binary);
	if (!in.is_open()) {
		return false;
	}
	ostringstream buffer;
	buffer << in.rdbuf();
	text = buffer.str();
	return true;
}

string stripComments(const string& text) {
	string result;
	bool in_line_comment = false;
	bool in_block_comment = false;
	for (size_t i = 0; i < text.size(); ++i) {
		if (in_line_comment) {
			if (text[i] == '\n' || text[i] == '\r') {
				in_line_comment = false;
				result += ' ';
			}
			continue;
		}
		if (in_block_comment) {
			if (text[i] == '*' && i + 1 < text.size() && text[i + 1] == '/') {
				in_block_comment = false;
				++i;
				continue;
			}
			if (text[i] == '\n' || text[i] == '\r' || text[i] == '\t') {
				result += ' ';
			}
			continue;
		}
		if (text[i] == '/' && i + 1 < text.size()) {
			if (text[i + 1] == '/') {
				in_line_comment = true;
				++i;
				continue;
			}
			if (text[i + 1] == '*') {
				in_block_comment = true;
				++i;
				continue;
			}
		}
		result += text[i];
	}
	return result;
}

string normalizeWhitespace(const string& text) {
	string result;
	bool last_is_space = false;
	for (size_t i = 0; i < text.size(); ++i) {
		unsigned char ch = static_cast<unsigned char>(text[i]);
		if (isspace(ch)) {
			if (!result.empty() && !last_is_space) {
				result += ' ';
				last_is_space = true;
			}
			continue;
		}
		result += static_cast<char>(ch);
		last_is_space = false;
	}
	if (!result.empty() && result.back() == ' ') {
		result.erase(result.end() - 1);
	}
	return result;
}

bool isWordChar(char ch) {
	unsigned char value = static_cast<unsigned char>(ch);
	return isalnum(value) || ch == '_';
}

bool isTokenPunctuation(char ch) {
	return ispunct(static_cast<unsigned char>(ch)) && ch != '_';
}

string deriveOriginalFile(const string& processedFile) {
	if (!g_source_file_name.empty()) {
		return g_source_file_name;
	}
	size_t pos = processedFile.find_last_of("/\\");
	if (pos == string::npos) {
		return "./testCpp.txt";
	}
	return processedFile.substr(0, pos + 1) + "testCpp.txt";
}
}


