string load_file(string file_name) {
	fstream fs;
	fs.open(file_name.c_str(), ios::in);
	if (!fs) {
		cout << "文件不存在!";
		return "";
	}
	istreambuf_iterator<char> beg(fs), end;
	string code(beg, end);
	cout << "读取文件中..." << endl;
	cout << "文件内容如下：" << endl;
	cout << code << endl;
	fs.close();
	return code;
}
ostream& operator << (ostream& out, rule rule) {
	string ret;

	string ret;
	if (rule.left != ' ') {
		ret += rule.left;
		ret += "::=";
		for (size_t i = 0; i < rule.right.size(); ++i) {
			if (i != 0) {
				ret += '|';
			}
			ret += rule.right[i];
		}
	}
	out << ret;
	return out;
}
void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	stringstream ss(text);
	string token;
	while (ss >> token) {
		size_t pos = token.find("::=");
		if (pos == string::npos || pos == 0) {
			continue;
		}

		rule temp_rule;
		temp_rule.left = token[0];
		non_terminal.insert(temp_rule.left);

		string right_text = token.substr(pos + 3);
		size_t start = 0;
		while (start <= right_text.size()) {
			size_t split = right_text.find('|', start);
			string right_part = right_text.substr(start, split - start);
			temp_rule.right.push_back(right_part);
			right_parts.insert(right_part);
			for (size_t i = 0; i < right_part.size(); ++i) {
				if (!isupper(static_cast<unsigned char>(right_part[i]))) {
					terminal.insert(right_part[i]);
				}
			}
			if (split == string::npos) {
				break;
			}
			start = split + 1;
		}
		rules.push_back(temp_rule);
	}
}
