LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
	vector<char> table_head;
	for (set<char>::iterator it = terminal.begin(); it != terminal.end(); ++it) {
		if (*it != '@') {
			table_head.push_back(*it);
		}
	}
	table_head.push_back('#');

	LL_1_table table;
	table.row = ordered_rows(non_terminal, rules);
	table.col = table_head;
	for (size_t i = 0; i < table.row.size() * table.col.size(); ++i) {
		rule rule_temp;
		rule_temp.left = ' ';
		table.rules.push_back(rule_temp);
	}

	for (size_t i = 0; i < rules.size(); ++i) {
		for (size_t j = 0; j < rules[i].right.size(); ++j) {
			set<char> first_set = findFirst(rules[i].right[j], rules).right;
			bool has_epsilon = false;
			for (set<char>::iterator it = first_set.begin(); it != first_set.end(); ++it) {
				if (*it == '@') {
					has_epsilon = true;
					continue;
				}
				int col = table_index(table.col, *it);
				int row = table_index(table.row, rules[i].left);
				if (row >= 0 && col >= 0) {
					table.rules[row * table.col.size() + col].left = rules[i].left;
					table.rules[row * table.col.size() + col].right.clear();
					table.rules[row * table.col.size() + col].right.push_back(rules[i].right[j]);
				}
			}
			if (has_epsilon) {
				set<char> follow_set = findFollow(rules[i].left, rules).right;
				for (set<char>::iterator it = follow_set.begin(); it != follow_set.end(); ++it) {
					int col = table_index(table.col, *it);
					int row = table_index(table.row, rules[i].left);
					if (row >= 0 && col >= 0) {
						table.rules[row * table.col.size() + col].left = rules[i].left;
						table.rules[row * table.col.size() + col].right.clear();
						table.rules[row * table.col.size() + col].right.push_back(rules[i].right[j]);
					}
				}
			}
		}
	}
	return table;
}
ostream& operator << (ostream& out, LL_1_table table) {
	out << endl << "LL(1)分析表如下：" << endl;
	int width = 10;
	out << setw(3) << " ";
	for (size_t i = 0; i < table.col.size(); ++i) {
		out << setw(width) << table.col[i];
	}
	out << endl;

	for (size_t i = 0; i < table.rules.size(); ++i) {
		if (i % table.col.size() == 0) {
			out << setw(3) << table.row[i / table.col.size()];
		}
		out << setw(width) << table.rules[i];
		if ((i + 1) % table.col.size() == 0) {
			out << endl;
		}
	}
	return out;
}
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
	string left_str, right_str;
	char temp_char;
	int len_left = static_cast<int>(analysis_s.size());
	int len_right = static_cast<int>(input_s.size());

	stack<char> temp;
	for (int i = 0; i < len_left; i++) {
		temp.push(analysis_s.top());
		analysis_s.pop();
	}
	for (int i = 0; i < len_left; i++) {
		temp_char = temp.top();
		left_str = left_str + temp_char;
		temp.pop();
	}
	for (int i = 0; i < len_right; i++) {
		temp_char = input_s.top();
		right_str = right_str + temp_char;
		input_s.pop();
	}
	cout << endl << left << setw(10) << left_str << right << setw(10) << right_str << setw(5) << " " << left << setw(20) << rule_temp;
}
void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;

	stack<char> input_s;
	input_s.push('#');
	for (int i = static_cast<int>(input.size()) - 1; i >= 0; i--) {
		input_s.push(input[i]);
	}
	stack<char> analysis_s;
	analysis_s.push('#');
	analysis_s.push(table.row.empty() ? 'E' : table.row.front());

	cout << left << setw(10) << "分析栈" << right << setw(10) << "预留输入串栈" << setw(5) << "" << left << setw(10) << "产生式";
	bool flag = true;
	while (flag && !(analysis_s.empty() || input_s.empty())) {
		char left_ch = analysis_s.top();
		char right_ch = input_s.top();
		if (isupper(static_cast<unsigned char>(left_ch))) {
			int row = table_index(table.row, left_ch);
			int col = table_index(table.col, right_ch);
			rule rule_temp;
			rule_temp.left = ' ';
			if (row >= 0 && col >= 0) {
				rule_temp = table.rules[row * table.col.size() + col];
			}
			print_state(analysis_s, input_s, rule_temp);
			if (row < 0 || col < 0 || rule_temp.left == ' ' || rule_temp.right.empty()) {
				flag = false;
				break;
			}

			analysis_s.pop();
			if (rule_temp.right[0] != "@") {
				string temp_str = rule_temp.right[0];
				for (int i = static_cast<int>(temp_str.size()) - 1; i >= 0; i--) {
					analysis_s.push(temp_str[i]);
				}
			}
		}
		else {
			rule rule_temp;
			rule_temp.left = ' ';
			print_state(analysis_s, input_s, rule_temp);
			if (left_ch == right_ch) {
				analysis_s.pop();
				input_s.pop();
			}
			else {
				flag = false;
				break;
			}
		}
	}
	if (!(analysis_s.empty() && input_s.empty())) {
		flag = false;
	}

